import{_ as t,o as a,c as i,a as n}from"./app.BAI08CEQ.js";const m=JSON.parse('{"title":"Model Selection Documentation Index","description":"","frontmatter":{},"headers":[],"relativePath":"reference/MODEL_SELECTION_INDEX.md","filePath":"reference/MODEL_SELECTION_INDEX.md","lastUpdated":1771753292000}'),o={name:"reference/MODEL_SELECTION_INDEX.md"};function r(s,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="model-selection-documentation-index" tabindex="-1">Model Selection Documentation Index <a class="header-anchor" href="#model-selection-documentation-index" aria-label="Permalink to &quot;Model Selection Documentation Index&quot;">​</a></h1><p><strong>Purpose</strong>: Central index for all model selection, Pareto frontier, and routing documentation</p><p><strong>Status</strong>: Complete reference set <strong>Last Updated</strong>: 2026-02-15</p><hr><h2 id="quick-answer-to-where-is-model" tabindex="-1">Quick Answer to &quot;Where is [Model]?&quot; <a class="header-anchor" href="#quick-answer-to-where-is-model" aria-label="Permalink to &quot;Quick Answer to &quot;Where is [Model]?&quot;&quot;">​</a></h2><h3 id="glm-5-92-7-aime-2-60-m" tabindex="-1">GLM-5 (92.7% AIME, $2.60/M) <a class="header-anchor" href="#glm-5-92-7-aime-2-60-m" aria-label="Permalink to &quot;GLM-5 (92.7% AIME, $2.60/M)&quot;">​</a></h3><p><strong>Status</strong>: OFF frontier <strong>Why</strong>: Dominated by MiniMax on cost-value (3.3x more expensive) for general tasks, and by Opus on reasoning reliability (Opus 85% AIME vs GLM-5 92.7%, but Opus more reliable for mixed code+reasoning)</p><p><strong>Location</strong>: See <code>/docs/reference/PARETO_FRONTIER_COMPLETE_ANALYSIS.md</code> → &quot;GLM-5 (92.7% AIME) — Why Not Selected?&quot;</p><hr><h3 id="claude-opus-4-6-80-8-swe-bench-17-50-m" tabindex="-1">Claude Opus 4.6 (80.8% SWE-Bench, $17.50/M) <a class="header-anchor" href="#claude-opus-4-6-80-8-swe-bench-17-50-m" aria-label="Permalink to &quot;Claude Opus 4.6 (80.8% SWE-Bench, $17.50/M)&quot;">​</a></h3><p><strong>Status</strong>: ON frontier, but RESERVED for mission-critical only <strong>Why</strong>: Best quality (80.8%), but costs 22x more than MiniMax for only 0.6% improvement. Reserved for HIGH_COMPLEX tier when quality is absolute requirement (not preference)</p><p><strong>Location</strong>: See <code>/docs/reference/PARETO_FRONTIER_COMPLETE_ANALYSIS.md</code> → &quot;Claude Opus 4.6 — Why Reserved for Premium Only?&quot;</p><p><strong>When to use</strong>: <code>mission_critical = True</code> (medical, financial, legal diagnosis)</p><hr><h3 id="claude-sonnet-4-5-77-2-swe-bench-10-50-m" tabindex="-1">Claude Sonnet 4.5 (77.2% SWE-Bench, $10.50/M) <a class="header-anchor" href="#claude-sonnet-4-5-77-2-swe-bench-10-50-m" aria-label="Permalink to &quot;Claude Sonnet 4.5 (77.2% SWE-Bench, $10.50/M)&quot;">​</a></h3><p><strong>Status</strong>: OFF frontier <strong>Why</strong>: Dominated by MiniMax on both quality (80.2% &gt; 77.2%) and cost ($0.79 &lt; $10.50). MiniMax is 13.3x cheaper for higher quality.</p><p><strong>Location</strong>: See <code>/docs/reference/PARETO_FRONTIER_COMPLETE_ANALYSIS.md</code> → &quot;Claude Sonnet 4.5 — Why Dominated?&quot;</p><hr><h3 id="gemini-3-flash-78-swe-bench-218-tok-s-1-50-m" tabindex="-1">Gemini 3 Flash (78% SWE-Bench, 218 tok/s, $1.50/M) <a class="header-anchor" href="#gemini-3-flash-78-swe-bench-218-tok-s-1-50-m" aria-label="Permalink to &quot;Gemini 3 Flash (78% SWE-Bench, 218 tok/s, $1.50/M)&quot;">​</a></h3><p><strong>Status</strong>: OFF frontier (quality-cost), but available as speed fallback <strong>Why</strong>: Dominated by MiniMax on cost-quality (80.2% &gt; 78%, $0.79 &lt; $1.50). But ultra-fast (218 tok/s) makes it acceptable fallback for &lt;300ms latency SLA.</p><p><strong>Location</strong>: See <code>/docs/reference/PARETO_FRONTIER_COMPLETE_ANALYSIS.md</code> → &quot;Gemini 3 Flash — Why Off Frontier Despite Speed?&quot;</p><p><strong>When to use</strong>: <code>latency_sla &lt; 300ms</code> AND MiniMax doesn&#39;t fit</p><hr><h3 id="gpt-5-3-codex-56-8-swe-bench-1-25-m-codex-spark-50-1-00-m" tabindex="-1">GPT-5.3-Codex (56.8% SWE-Bench, $1.25/M) &amp; Codex-Spark (~50%, ~$1.00/M) <a class="header-anchor" href="#gpt-5-3-codex-56-8-swe-bench-1-25-m-codex-spark-50-1-00-m" aria-label="Permalink to &quot;GPT-5.3-Codex (56.8% SWE-Bench, $1.25/M) &amp; Codex-Spark (~50%, ~$1.00/M)&quot;">​</a></h3><p><strong>Status</strong>: REJECTED <strong>Why</strong>: Both fail quality floor (60% minimum). Also dominated by GPT-4o mini: 70% quality, $0.375/M beats Codex on BOTH quality and cost.</p><p><strong>Location</strong>: See <code>/docs/reference/PARETO_FRONTIER_COMPLETE_ANALYSIS.md</code> → &quot;GPT-5.3-Codex &amp; GPT-5.3-Codex-Spark — Why Rejected?&quot;</p><p><strong>Verdict</strong>: Never use. GPT-4o mini is cheaper and higher quality.</p><hr><h3 id="gemini-2-5-pro-75-swe-bench-4-07-m-multi-modal" tabindex="-1">Gemini 2.5 Pro (75% SWE-Bench, $4.07/M, multi-modal) <a class="header-anchor" href="#gemini-2-5-pro-75-swe-bench-4-07-m-multi-modal" aria-label="Permalink to &quot;Gemini 2.5 Pro (75% SWE-Bench, $4.07/M, multi-modal)&quot;">​</a></h3><p><strong>Status</strong>: OFF frontier (quality-cost), but available for image tasks <strong>Why</strong>: Dominated by MiniMax on cost-quality (80.2% &gt; 75%, $0.79 &lt; $4.07). But multi-modal capability makes it acceptable for image+text input.</p><p><strong>Location</strong>: See <code>/docs/reference/PARETO_FRONTIER_COMPLETE_ANALYSIS.md</code> → &quot;Gemini 2.5 Pro — Why Dominated?&quot;</p><p><strong>When to use</strong>: <code>multi_modal_required = True</code> AND cost permits</p><hr><h2 id="documentation-organization" tabindex="-1">Documentation Organization <a class="header-anchor" href="#documentation-organization" aria-label="Permalink to &quot;Documentation Organization&quot;">​</a></h2><h3 id="document-1-complete-pareto-frontier-analysis" tabindex="-1">Document 1: Complete Pareto Frontier Analysis <a class="header-anchor" href="#document-1-complete-pareto-frontier-analysis" aria-label="Permalink to &quot;Document 1: Complete Pareto Frontier Analysis&quot;">​</a></h3><p><strong>File</strong>: <code>PARETO_FRONTIER_COMPLETE_ANALYSIS.md</code><strong>Length</strong>: ~1500 lines <strong>Audience</strong>: Detailed explanation seekers</p><p><strong>Contents</strong>:</p><ul><li>Full 14-model comparison table</li><li>Dominance relationships (ASCII chart)</li><li>Per-model detailed explanations (GLM-5, Opus, Sonnet, Gemini Flash, Codex, Gemini Pro)</li><li>Category assignment justification with budget tier analysis</li><li>Accuracy metrics explained (SWE-Bench, AIME, GPQA, MMLU)</li><li>Cost-quality trade-off chart</li><li>Summary decision matrix</li></ul><p><strong>Start here if</strong>: You want to understand WHY each model is on/off frontier with full context</p><hr><h3 id="document-2-model-routing-decision-tree" tabindex="-1">Document 2: Model Routing Decision Tree <a class="header-anchor" href="#document-2-model-routing-decision-tree" aria-label="Permalink to &quot;Document 2: Model Routing Decision Tree&quot;">​</a></h3><p><strong>File</strong>: <code>MODEL_ROUTING_DECISION_TREE.md</code><strong>Length</strong>: ~1000 lines <strong>Audience</strong>: Implementers, programmatic selection</p><p><strong>Contents</strong>:</p><ul><li>Quick reference (3-model frontier summary)</li><li>Pseudocode decision tree (Python-like)</li><li>English-language decision tree (flowchart)</li><li>6 real-world examples: <ol><li>Rapid document classification (FAST tier)</li><li>Real-time chat with latency SLA (speed-critical)</li><li>Mission-critical medical diagnosis (HIGH_COMPLEX)</li><li>Code refactoring with budget constraint (COMPLEX)</li><li>Pure reasoning math problem (reasoning-heavy)</li><li>Multi-modal image analysis (image-specific)</li></ol></li><li>Fallback chains (provider outage scenarios)</li><li>Summary table: when to use each model</li></ul><p><strong>Start here if</strong>: You&#39;re building the router logic or need to implement decision tree</p><hr><h3 id="document-3-pareto-frontier-quick-reference" tabindex="-1">Document 3: Pareto Frontier Quick Reference <a class="header-anchor" href="#document-3-pareto-frontier-quick-reference" aria-label="Permalink to &quot;Document 3: Pareto Frontier Quick Reference&quot;">​</a></h3><p><strong>File</strong>: <code>PARETO_FRONTIER_QUICK_REFERENCE.md</code><strong>Length</strong>: ~400 lines <strong>Audience</strong>: Quick lookup, managers, decision makers</p><p><strong>Contents</strong>:</p><ul><li>The 3-model frontier (TL;DR)</li><li>Your questions answered (GLM-5, Opus, Codex, etc.)</li><li>Why only 3 models?</li><li>Cost-quality efficiency table</li><li>Quick decision rules (5 basic rules)</li><li>Model comparison matrix (ASCII)</li><li>When to escalate to humans</li><li>Summary table: when to use each model</li><li>Further reading references</li></ul><p><strong>Start here if</strong>: You want a 5-minute overview without details</p><hr><h3 id="document-4-dominance-proof-reference" tabindex="-1">Document 4: Dominance Proof Reference <a class="header-anchor" href="#document-4-dominance-proof-reference" aria-label="Permalink to &quot;Document 4: Dominance Proof Reference&quot;">​</a></h3><p><strong>File</strong>: <code>DOMINANCE_PROOF_REFERENCE.md</code><strong>Length</strong>: ~600 lines <strong>Audience</strong>: Verification, quality assurance, academic rigor</p><p><strong>Contents</strong>:</p><ul><li>Dominance definition (mathematical)</li><li>7 detailed dominance proofs: <ol><li>MiniMax dominates Sonnet (quality + cost)</li><li>GPT-4o mini dominates Codex (quality + cost)</li><li>MiniMax dominates Gemini Flash (quality + cost)</li><li>MiniMax dominates Gemini Pro (quality + cost)</li><li>GLM-5 niche analysis (specialized reasoning)</li><li>Opus niche analysis (mission-critical quality)</li><li>Codex-Spark floor check (quality rejection)</li></ol></li><li>Dominance summary table</li><li>Quality floor analysis by category</li><li>Efficiency analysis (cost per quality %)</li><li>Conclusion (why only 3 models)</li></ul><p><strong>Start here if</strong>: You need to verify the selection logic with mathematical rigor</p><hr><h3 id="document-5-this-index" tabindex="-1">Document 5: This Index <a class="header-anchor" href="#document-5-this-index" aria-label="Permalink to &quot;Document 5: This Index&quot;">​</a></h3><p><strong>File</strong>: <code>MODEL_SELECTION_INDEX.md</code></p><p><strong>Contents</strong>:</p><ul><li>Quick answers to common questions</li><li>Document organization guide</li><li>Which document to read based on need</li><li>Usage scenarios</li></ul><hr><h2 id="how-to-use-this-documentation" tabindex="-1">How to Use This Documentation <a class="header-anchor" href="#how-to-use-this-documentation" aria-label="Permalink to &quot;How to Use This Documentation&quot;">​</a></h2><h3 id="scenario-1-why-is-model-not-selected" tabindex="-1">Scenario 1: &quot;Why is [model] not selected?&quot; <a class="header-anchor" href="#scenario-1-why-is-model-not-selected" aria-label="Permalink to &quot;Scenario 1: &quot;Why is [model] not selected?&quot;&quot;">​</a></h3><p>→ Read <code>/docs/reference/PARETO_FRONTIER_QUICK_REFERENCE.md</code> (section &quot;Your Questions Answered&quot;)</p><h3 id="scenario-2-i-need-to-implement-the-router" tabindex="-1">Scenario 2: &quot;I need to implement the router&quot; <a class="header-anchor" href="#scenario-2-i-need-to-implement-the-router" aria-label="Permalink to &quot;Scenario 2: &quot;I need to implement the router&quot;&quot;">​</a></h3><p>→ Read <code>/docs/reference/MODEL_ROUTING_DECISION_TREE.md</code> (Python pseudocode + examples)</p><h3 id="scenario-3-i-want-to-understand-the-full-analysis" tabindex="-1">Scenario 3: &quot;I want to understand the full analysis&quot; <a class="header-anchor" href="#scenario-3-i-want-to-understand-the-full-analysis" aria-label="Permalink to &quot;Scenario 3: &quot;I want to understand the full analysis&quot;&quot;">​</a></h3><p>→ Read <code>/docs/reference/PARETO_FRONTIER_COMPLETE_ANALYSIS.md</code> (comprehensive, 1500 lines)</p><h3 id="scenario-4-i-need-to-verify-the-logic-is-correct" tabindex="-1">Scenario 4: &quot;I need to verify the logic is correct&quot; <a class="header-anchor" href="#scenario-4-i-need-to-verify-the-logic-is-correct" aria-label="Permalink to &quot;Scenario 4: &quot;I need to verify the logic is correct&quot;&quot;">​</a></h3><p>→ Read <code>/docs/reference/DOMINANCE_PROOF_REFERENCE.md</code> (mathematical proofs)</p><h3 id="scenario-5-i-m-explaining-this-to-non-technical-stakeholder" tabindex="-1">Scenario 5: &quot;I&#39;m explaining this to non-technical stakeholder&quot; <a class="header-anchor" href="#scenario-5-i-m-explaining-this-to-non-technical-stakeholder" aria-label="Permalink to &quot;Scenario 5: &quot;I&#39;m explaining this to non-technical stakeholder&quot;&quot;">​</a></h3><p>→ Show <code>/docs/reference/PARETO_FRONTIER_QUICK_REFERENCE.md</code> (visual, simple rules)</p><h3 id="scenario-6-what-should-i-do-in-situation-x" tabindex="-1">Scenario 6: &quot;What should I do in situation X?&quot; <a class="header-anchor" href="#scenario-6-what-should-i-do-in-situation-x" aria-label="Permalink to &quot;Scenario 6: &quot;What should I do in situation X?&quot;&quot;">​</a></h3><p>→ Use <code>/docs/reference/MODEL_ROUTING_DECISION_TREE.md</code> (find matching example or trace through tree)</p><hr><h2 id="key-concepts-glossary" tabindex="-1">Key Concepts (Glossary) <a class="header-anchor" href="#key-concepts-glossary" aria-label="Permalink to &quot;Key Concepts (Glossary)&quot;">​</a></h2><h3 id="pareto-frontier" tabindex="-1">Pareto Frontier <a class="header-anchor" href="#pareto-frontier" aria-label="Permalink to &quot;Pareto Frontier&quot;">​</a></h3><p>Set of solutions where no solution dominates another on all dimensions. A model is ON the frontier if no other model beats it on 2+ dimensions simultaneously.</p><p><strong>Example</strong>:</p><ul><li>MiniMax (80.2% quality, $0.79/M) is on frontier</li><li>Sonnet (77.2% quality, $10.50/M) is OFF frontier (MiniMax beats it on quality AND cost)</li></ul><h3 id="dominance" tabindex="-1">Dominance <a class="header-anchor" href="#dominance" aria-label="Permalink to &quot;Dominance&quot;">​</a></h3><p>Model A dominates Model B if A is ≥ B on all dimensions and strictly better on ≥2 dimensions.</p><p><strong>Example</strong>: MiniMax dominates Sonnet</p><ul><li>Quality: 80.2% &gt; 77.2% ✓ (strictly better)</li><li>Cost: $0.79 &lt; $10.50 ✓ (strictly better)</li><li>Speed: moderate = moderate (tie) → MiniMax is strictly better on 2 dimensions → dominates</li></ul><h3 id="quality-floor" tabindex="-1">Quality Floor <a class="header-anchor" href="#quality-floor" aria-label="Permalink to &quot;Quality Floor&quot;">​</a></h3><p>Minimum acceptable quality for a given category. Models below floor are REJECTED.</p><p><strong>Example</strong>: Quality floor for NORMAL tasks = 70%</p><ul><li>GPT-4o mini: 70% ✓ (meets floor)</li><li>Codex: 56.8% ✗ (below floor, rejected)</li></ul><h3 id="cost-per-quality-point" tabindex="-1">Cost Per Quality Point <a class="header-anchor" href="#cost-per-quality-point" aria-label="Permalink to &quot;Cost Per Quality Point&quot;">​</a></h3><p>Cost divided by quality percentage. Measure of efficiency.</p><p><strong>Example</strong>:</p><ul><li>GPT-4o mini: $0.375 / 70% = $0.00536 per % (most efficient)</li><li>MiniMax: $0.79 / 80.2% = $0.00985 per % (good balance)</li><li>Opus: $17.50 / 80.8% = $0.21655 per % (least efficient)</li></ul><h3 id="frontier-tier" tabindex="-1">Frontier Tier <a class="header-anchor" href="#frontier-tier" aria-label="Permalink to &quot;Frontier Tier&quot;">​</a></h3><p>Category within the Pareto frontier based on use case</p><p><strong>Tiers</strong>:</p><ol><li><strong>Tier 1 (Fallback)</strong>: GPT-4o mini — cost minimum</li><li><strong>Tier 2 (Primary)</strong>: MiniMax M2.5 — cost-quality sweet spot</li><li><strong>Tier 3 (Premium)</strong>: Claude Opus 4.6 — mission-critical quality</li></ol><h3 id="budget-tier" tabindex="-1">Budget Tier <a class="header-anchor" href="#budget-tier" aria-label="Permalink to &quot;Budget Tier&quot;">​</a></h3><p>Cost allocation category for task routing</p><p><strong>Tiers</strong>:</p><ol><li><strong>FAST</strong>: &lt;$0.0005/call (short inputs, &lt;500 tokens)</li><li><strong>NORMAL</strong>: $0.001-$0.05/call (standard, 1-3K tokens)</li><li><strong>COMPLEX</strong>: $0.05-$0.15/call (advanced, 3-8K tokens)</li><li><strong>HIGH_COMPLEX</strong>: &gt;$0.85/call (mission-critical, 10K+ tokens)</li></ol><hr><h2 id="model-quick-reference" tabindex="-1">Model Quick Reference <a class="header-anchor" href="#model-quick-reference" aria-label="Permalink to &quot;Model Quick Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Tier</th><th>Status</th><th>Quality</th><th>Cost</th><th>When To Use</th></tr></thead><tbody><tr><td>GPT-4o mini</td><td>1</td><td>FRONTIER</td><td>70%</td><td>$0.375/M</td><td>Cost absolute minimum</td></tr><tr><td>MiniMax M2.5</td><td>2</td><td>PRIMARY</td><td>80.2%</td><td>$0.79/M</td><td>DEFAULT (95% of tasks)</td></tr><tr><td>Claude Opus 4.6</td><td>3</td><td>PREMIUM</td><td>80.8%</td><td>$17.50/M</td><td>mission_critical = True</td></tr><tr><td>Gemini Flash</td><td>-</td><td>FALLBACK</td><td>78%</td><td>$1.50/M</td><td>latency &lt; 300ms</td></tr><tr><td>GLM-5</td><td>-</td><td>NICHE</td><td>92.7% AIME</td><td>$2.60/M</td><td>Pure reasoning only</td></tr><tr><td>Gemini 2.5 Pro</td><td>-</td><td>FALLBACK</td><td>75%</td><td>$4.07/M</td><td>Image + text required</td></tr><tr><td>Sonnet 4.5</td><td>-</td><td>DOMINATED</td><td>77.2%</td><td>$10.50/M</td><td>MiniMax unavailable (fallback)</td></tr><tr><td>Codex 5.3</td><td>-</td><td>REJECTED</td><td>56.8%</td><td>$1.25/M</td><td>NEVER (use GPT-4o mini)</td></tr><tr><td>Codex-Spark</td><td>-</td><td>REJECTED</td><td>~50%</td><td>~$1.00/M</td><td>NEVER (use GPT-4o mini)</td></tr></tbody></table><hr><h2 id="decision-tree-summary" tabindex="-1">Decision Tree Summary <a class="header-anchor" href="#decision-tree-summary" aria-label="Permalink to &quot;Decision Tree Summary&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>START</span></span>
<span class="line"><span>  ├─ mission_critical = True?</span></span>
<span class="line"><span>  │   ├─ YES → Use Claude Opus 4.6</span></span>
<span class="line"><span>  │   └─ NO  → Continue</span></span>
<span class="line"><span>  ├─ latency_sla &lt; 300ms?</span></span>
<span class="line"><span>  │   ├─ YES → Use Gemini 3 Flash (if in budget), else MiniMax</span></span>
<span class="line"><span>  │   └─ NO  → Continue</span></span>
<span class="line"><span>  ├─ reasoning_heavy AND quality &gt; 85%?</span></span>
<span class="line"><span>  │   ├─ YES → Use GLM-5 or Opus (if budget permits)</span></span>
<span class="line"><span>  │   └─ NO  → Continue</span></span>
<span class="line"><span>  ├─ multi_modal_required?</span></span>
<span class="line"><span>  │   ├─ YES → Use Gemini 2.5 Pro (if in budget), else MiniMax</span></span>
<span class="line"><span>  │   └─ NO  → Continue</span></span>
<span class="line"><span>  └─ DEFAULT</span></span>
<span class="line"><span>      └─ Use MiniMax M2.5 (universal fallback)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><hr><h2 id="integration-points" tabindex="-1">Integration Points <a class="header-anchor" href="#integration-points" aria-label="Permalink to &quot;Integration Points&quot;">​</a></h2><h3 id="cost-governance-system" tabindex="-1">Cost Governance System <a class="header-anchor" href="#cost-governance-system" aria-label="Permalink to &quot;Cost Governance System&quot;">​</a></h3><p>The model router integrates with cost governance to enforce budget constraints:</p><ul><li>Task budget (in cents per call) is checked against model cost</li><li>If budget &lt; model cost: try fallback</li><li>If all models exceed budget: escalate to human queue</li></ul><h3 id="quality-assurance" tabindex="-1">Quality Assurance <a class="header-anchor" href="#quality-assurance" aria-label="Permalink to &quot;Quality Assurance&quot;">​</a></h3><p>Models selected must meet category quality floor:</p><ul><li>FAST: ≥ 60% quality</li><li>NORMAL: ≥ 70% quality</li><li>COMPLEX: ≥ 75% quality</li><li>HIGH_COMPLEX: ≥ 80% quality</li></ul><h3 id="sla-monitoring" tabindex="-1">SLA Monitoring <a class="header-anchor" href="#sla-monitoring" aria-label="Permalink to &quot;SLA Monitoring&quot;">​</a></h3><p>Latency SLA compliance:</p><ul><li>If SLA &lt; 300ms: switch to Gemini 3 Flash (218 tok/s) or error</li><li>If SLA &lt; 500ms: MiniMax or Gemini as tradeoff</li><li>If SLA &gt; 500ms: standard MiniMax routing</li></ul><hr><h2 id="future-updates" tabindex="-1">Future Updates <a class="header-anchor" href="#future-updates" aria-label="Permalink to &quot;Future Updates&quot;">​</a></h2><h3 id="when-benchmarks-change" tabindex="-1">When Benchmarks Change <a class="header-anchor" href="#when-benchmarks-change" aria-label="Permalink to &quot;When Benchmarks Change&quot;">​</a></h3><ul><li>Update quality % in all documents</li><li>Recalculate dominance relationships</li><li>Verify frontier remains 3-model</li><li>Note: date of benchmark update in header</li></ul><h3 id="when-pricing-changes" tabindex="-1">When Pricing Changes <a class="header-anchor" href="#when-pricing-changes" aria-label="Permalink to &quot;When Pricing Changes&quot;">​</a></h3><ul><li>Update $/M in all tables</li><li>Recalculate cost per quality %</li><li>Verify MiniMax remains optimal</li><li>If price changes &gt;10%: recompute frontier</li></ul><h3 id="when-new-models-released" tabindex="-1">When New Models Released <a class="header-anchor" href="#when-new-models-released" aria-label="Permalink to &quot;When New Models Released&quot;">​</a></h3><ul><li>Add row to comparison table</li><li>Run dominance check against 3-frontier models</li><li>If dominated: mark as fallback/niche</li><li>If on frontier: update tier assignments</li></ul><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><strong>Pareto Optimality</strong>: <a href="https://en.wikipedia.org/wiki/Pareto_efficiency" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Pareto_efficiency</a></li><li><strong>Cost-Quality Trade-offs</strong>: See &quot;Accuracy Metrics Explained&quot; in PARETO_FRONTIER_COMPLETE_ANALYSIS.md</li><li><strong>SWE-Bench</strong>: <a href="https://www.swe-bench.com/" target="_blank" rel="noreferrer">https://www.swe-bench.com/</a> (software engineering benchmarks)</li><li><strong>Pricing</strong>: January 2026 public API rates (see PARETO_FRONTIER_COMPLETE_ANALYSIS.md for sources)</li></ul><hr><h2 id="document-versions" tabindex="-1">Document Versions <a class="header-anchor" href="#document-versions" aria-label="Permalink to &quot;Document Versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Version</th><th>Date</th><th>Status</th></tr></thead><tbody><tr><td>PARETO_FRONTIER_COMPLETE_ANALYSIS.md</td><td>1.0</td><td>2026-02-15</td><td>Reference</td></tr><tr><td>MODEL_ROUTING_DECISION_TREE.md</td><td>1.0</td><td>2026-02-15</td><td>Reference</td></tr><tr><td>PARETO_FRONTIER_QUICK_REFERENCE.md</td><td>1.0</td><td>2026-02-15</td><td>Reference</td></tr><tr><td>DOMINANCE_PROOF_REFERENCE.md</td><td>1.0</td><td>2026-02-15</td><td>Reference</td></tr><tr><td>MODEL_SELECTION_INDEX.md (this)</td><td>1.0</td><td>2026-02-15</td><td>Reference</td></tr></tbody></table><hr><p><strong>Questions?</strong> Refer to the appropriate document above. For implementation, start with <code>MODEL_ROUTING_DECISION_TREE.md</code>. For understanding, start with <code>PARETO_FRONTIER_QUICK_REFERENCE.md</code>.</p><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>`,144)])])}const p=t(o,[["render",r]]);export{m as __pageData,p as default};
